using Documenter
using DocumenterCitations
using Literate
using SigmaTau
using Plots

Plots.gr()

# Render examples/*.jl into docs/src/tutorials/ (generated pages are gitignored).
const EXAMPLES_DIR  = joinpath(@__DIR__, "..", "examples")
const TUTORIALS_DIR = joinpath(@__DIR__, "src", "tutorials")
mkpath(TUTORIALS_DIR)
for jl in sort(readdir(EXAMPLES_DIR; join=true))
    endswith(jl, ".jl") || continue
    Literate.markdown(jl, TUTORIALS_DIR; documenter=true, credit=false)
end

# The cross-check report is generated by tools/validation/report.jl; publish it
# as a docs page (generated copy is gitignored).
let src = joinpath(@__DIR__, "..", "tools", "validation", "REPORT.md")
    body = replace(read(src, String),
                   r"^# Reference cross-check report"m => "# Cross-check report")
    write(joinpath(@__DIR__, "src", "explanation", "crosscheck.md"), body)
end

# The help of the explorer is its manual, written into the app by
# explorer_help.jl, which lists the pages. Stop when the app is behind them.
include("explorer_help.jl")
ExplorerHelp.check()

bib = CitationBibliography(joinpath(@__DIR__, "src", "refs.bib"); style=:authoryear)

DocMeta.setdocmeta!(SigmaTau, :DocTestSetup, :(using SigmaTau); recursive=true)

