        canonical  = "https://ianlap.github.io/SigmaTau.jl",
        mathengine = Documenter.MathJax3(),
        assets     = ["assets/sigmatau.css"],
        # The search index of all pages and docstrings is a little over the
        # default limit of 500 KiB.
        search_size_threshold_warn = 1024^2,
    ),
    plugins = [bib],
